on conflict (company_key) do update set
  company_name = excluded.company_name,
  official_url = excluded.official_url,
  status = excluded.status,
  evidence_text = excluded.evidence_text,
  evidence_url = excluded.evidence_url,
  last_checked_at = greatest(public.campus_recruitment_statuses.last_checked_at, excluded.last_checked_at),
  started_at = case
    when excluded.status = 'started' then coalesce(public.campus_recruitment_statuses.started_at, excluded.started_at)
    else null
  end,
  next_check_at = case
    when excluded.status = 'started' then null
    else greatest(public.campus_recruitment_statuses.next_check_at, excluded.next_check_at)
  end,
  error_message = null,
  updated_at = now(),
  check_count = public.campus_recruitment_statuses.check_count + 1;
